<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gruppen – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:950px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #bac5d1;border-radius:8px;margin:4px 0}button{padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;font-weight:700}.group{border:1px solid #e1e7ed;border-radius:10px;padding:13px}.message,.error{padding:10px;border-radius:8px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Gruppen</h1><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<section class="card"><h2>Gruppe erstellen</h2><form method="post" action="/community/groups"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><select name="group_type"><option value="INTEREST">Interessengruppe</option><option value="REGION">Regionale Gruppe</option></select><input name="name" placeholder="Name" required><textarea name="description" placeholder="Beschreibung"></textarea><input name="region_level" placeholder="Regionsebene optional, z. B. CITY"><input name="region_code" placeholder="Regionscode/Bezeichnung optional"><button type="submit">Erstellen</button></form></section>
<section class="card"><div class="grid"><?php foreach($groups as $g):?><div class="group"><strong><?= $e($g['name']) ?></strong><p><?= $e($g['description']??'') ?></p><small><?= $e($g['member_count']) ?> Mitglieder · <?= $e($g['group_type']) ?></small><?php if(empty($g['joined'])):?><form method="post" action="/community/groups/<?= rawurlencode($g['id']) ?>/join"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Beitreten</button></form><?php endif;?><p><a href="/community?group=<?= rawurlencode($g['id']) ?>">Beiträge anzeigen</a></p></div><?php endforeach;?></div></section>
</main></body></html>